import React, { useState, useEffect } from "react";
import axios from "axios";
//import { useNavigate } from "react-router-dom";
import { ShoppingCart } from "lucide-react";

const API_BASE_URL = "http://localhost:9091";

function UserShop() {
  const [medicines, setMedicines] = useState([]);
  const [cart, setCart] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    axios
      .get(`${API_BASE_URL}/api/medicines`)
      .then((res) => setMedicines(res.data))
      .catch((err) => console.error(err));
  }, []);

  const addToCart = (medicine) => {
    setCart((prev) => {
      const exist = prev.find((item) => item.id === medicine.id);
      if (exist)
        return prev.map((item) =>
          item.id === medicine.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      else return [...prev, { ...medicine, quantity: 1 }];
    });
  };

  const goToCart = () => {
    navigate("/cart", { state: { cart } });
  };

  return (
    <div className="p-8 max-w-6xl mx-auto">
      <h2 className="text-3xl font-bold text-indigo-700 mb-4">
        🩺 Medicine Shop
      </h2>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {medicines.map((med) => (
          <div
            key={med.id}
            className="bg-white p-5 shadow-md rounded-lg border border-gray-100"
          >
            <h3 className="font-semibold">{med.name}</h3>
            <p className="text-sm text-gray-600">{med.description}</p>
            <p className="font-bold text-green-600 mb-2">₹{med.price}</p>
            <button
              onClick={() => addToCart(med)}
              className="w-full bg-indigo-600 text-white py-2 rounded-lg hover:bg-indigo-700 transition"
            >
              Add to Cart
            </button>
          </div>
        ))}
      </div>

      {cart.length > 0 && (
        <div className="mt-6 flex justify-end">
          <button
            onClick={goToCart}
            className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 transition"
          >
            Go to Cart ({cart.length})
          </button>
        </div>
      )}
    </div>
  );
}

export default UserShop;
